-- Gold Query
SELECT CAST(SUM(t2.overall_rating) AS REAL) / COUNT(t2.id) FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t1.height > 170 AND SUBSTRING(t2."date", 1, 4) BETWEEN '2010' AND '2015';

/*
Gold Result:
(4.0,)
*/

-- Prediction Query
SELECT AVG("Player_Attributes"."overall_rating") FROM "Player_Attributes" INNER JOIN "Player" ON "Player_Attributes"."player_api_id" = "Player"."player_api_id" WHERE STRFTIME('%Y', "Player_Attributes"."date") BETWEEN '2010' AND '2015' AND "Player"."height" > 170;

